    // Auto-healing: Try multiple strategies to find an element when selectors fail
    private com.microsoft.playwright.Locator autoHealLocator(String elementDescription) {
        // Strategy 1: Exact text match
        try {
            com.microsoft.playwright.Locator locator = getPage().locator("text=" + elementDescription);
            if (locator.count() > 0) return locator.first();
        } catch (Exception e) { /* Continue to next strategy */ }

        // Strategy 2: Partial text match (case-insensitive)
        try {
            String normalized = elementDescription.toLowerCase().trim();
            com.microsoft.playwright.Locator locator = getPage().locator("text=/.*" + java.util.regex.Pattern.quote(normalized) + ".*/i");
            if (locator.count() > 0) return locator.first();
        } catch (Exception e) { /* Continue to next strategy */ }

        // Strategy 3: Aria-label containing the description
        try {
            com.microsoft.playwright.Locator locator = getPage().locator("[aria-label*='" + elementDescription + "']");
            if (locator.count() > 0) return locator.first();
        } catch (Exception e) { /* Continue to next strategy */ }

        // Strategy 4: Title attribute
        try {
            com.microsoft.playwright.Locator locator = getPage().locator("[title*='" + elementDescription + "']");
            if (locator.count() > 0) return locator.first();
        } catch (Exception e) { /* Continue to next strategy */ }

        // Strategy 5: Button or link with text
        try {
            com.microsoft.playwright.Locator locator = getPage().locator("button:has-text(\'" + elementDescription + "\'), a:has-text(\'" + elementDescription + "\'), input[type=\'button\'][value*=\'" + elementDescription + "\']");
            if (locator.count() > 0) return locator.first();
        } catch (Exception e) { /* Continue to next strategy */ }

        // Strategy 6: ID containing description (normalized)
        try {
            String idNormalized = elementDescription.toLowerCase().replaceAll("[^a-z0-9]", "");
            com.microsoft.playwright.Locator locator = getPage().locator("[id*='" + idNormalized + "']");
            if (locator.count() > 0) return locator.first();
        } catch (Exception e) { /* Continue to next strategy */ }

        // Strategy 7: Name attribute
        try {
            com.microsoft.playwright.Locator locator = getPage().locator("[name*='" + elementDescription.toLowerCase() + "']");
            if (locator.count() > 0) return locator.first();
        } catch (Exception e) { /* Continue to next strategy */ }

        // Strategy 8: Placeholder attribute (for inputs)
        try {
            com.microsoft.playwright.Locator locator = getPage().locator("[placeholder*='" + elementDescription + "']");
            if (locator.count() > 0) return locator.first();
        } catch (Exception e) { /* Continue to next strategy */ }

        // Strategy 9: Data attributes
        try {
            com.microsoft.playwright.Locator locator = getPage().locator("[data-testid*='" + elementDescription + "'], [data-id*='" + elementDescription + "'], [data-name*='" + elementDescription + "']");
            if (locator.count() > 0) return locator.first();
        } catch (Exception e) { /* Continue to next strategy */ }

        // Strategy 10: XPath with contains text (case-insensitive)
        try {
            String xpath = "//*[contains(translate(text(), \'ABCDEFGHIJKLMNOPQRSTUVWXYZ\', \'abcdefghijklmnopqrstuvwxyz\'), \'" + elementDescription.toLowerCase() + "\')]";
            com.microsoft.playwright.Locator locator = getPage().locator(xpath);
            if (locator.count() > 0) return locator.first();
        } catch (Exception e) { /* Continue to next strategy */ }

        // Strategy 11: Role-based with accessible name
        try {
            com.microsoft.playwright.Locator locator = getPage().getByRole(com.microsoft.playwright.options.AriaRole.BUTTON).filter(new com.microsoft.playwright.Locator.FilterOptions().setHasText(elementDescription));
            if (locator.count() > 0) return locator.first();
        } catch (Exception e) { /* Continue to next strategy */ }

        // Strategy 12: Link role
        try {
            com.microsoft.playwright.Locator locator = getPage().getByRole(com.microsoft.playwright.options.AriaRole.LINK).filter(new com.microsoft.playwright.Locator.FilterOptions().setHasText(elementDescription));
            if (locator.count() > 0) return locator.first();
        } catch (Exception e) { /* Continue to next strategy */ }

                // If all strategies fail, return a locator that will throw a descriptive error
        return getPage().locator("body"); // This will fail with a clear error message
    }

    // Helper method to try selectors with fallback and auto-healing
    private boolean tryClickWithFallback(java.util.List<String> selectors, String elementDescription) {
        if (selectors == null || selectors.isEmpty()) {
            selectors = new java.util.ArrayList<>();
            selectors.add(elementDescription);
        }
        for (String selector : selectors) {
            try {
                // Wait for element to be visible and enabled before clicking
                com.microsoft.playwright.Locator locator;
                if (selector.startsWith("text=") || selector.startsWith("#") || selector.startsWith(".") || selector.startsWith("[") || selector.startsWith("role=")) {
                    locator = getPage().locator(selector);
                } else if (selector.startsWith("xpath=")) {
                    locator = getPage().locator(selector.substring(6)); // Remove "xpath=" prefix
                } else {
                    locator = getPage().locator(selector);
                }
                // Wait for element to be visible and enabled
                locator.waitFor(new com.microsoft.playwright.Locator.WaitForOptions().setState(com.microsoft.playwright.options.WaitForSelectorState.VISIBLE).setTimeout(10000));

                // Detect if click causes navigation (pagination, links, etc.)
                String urlBeforeClick = getPage().url();

                // Perform the click
                locator.click();

                // Wait a bit for potential navigation to start
                try {
                    Thread.sleep(200);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }

                // Check if navigation occurred
                String urlAfterClick = getPage().url();
                if (!urlBeforeClick.equals(urlAfterClick)) {
                    // Navigation occurred - wait for page to stabilize
                    System.out.println("[Click] Navigation detected after clicking, waiting for page to load...");
