                        Thread.sleep(500);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
                return true;
            } catch (Exception e) {
                // Try next selector
                continue;
            }
        }
        // Auto-healing: If all recorded selectors failed, try intelligent element discovery
        try {
            com.microsoft.playwright.Locator locator = autoHealLocator(elementDescription);
            locator.waitFor(new com.microsoft.playwright.Locator.WaitForOptions().setState(com.microsoft.playwright.options.WaitForSelectorState.VISIBLE).setTimeout(10000));

            // Detect if click causes navigation (pagination, links, etc.)
