                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            System.out.println("[Auto-Healing] Successfully found and clicked element: " + elementDescription);
            return true;
        } catch (Exception e) {
            System.err.println("[Auto-Healing] Failed to find element: " + elementDescription + " - " + e.getMessage());
            throw new RuntimeException("Could not find element: " + elementDescription, e);
        }
    }

